import csv
import io
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation


def summarize_csv(text: str) -> dict:
    reader = csv.reader(io.StringIO(text))
    rows = list(reader)

    if not rows or rows[0] != ["sku", "amount"]:
        raise ValueError("Header must be exactly sku,amount")

    aggregates: dict[str, Decimal] = {}

    for row in rows[1:]:
        if not row or all(f.strip() == "" for f in row):
            continue
        if len(row) != 2:
            raise ValueError(f"Expected 2 fields, got {len(row)}")
        sku = row[0].strip()
        amt_str = row[1].strip()
        if sku == "":
            raise ValueError("Empty sku")
        try:
            amt = Decimal(amt_str)
        except (InvalidOperation, ValueError):
            raise ValueError(f"Malformed decimal amount: {amt_str!r}")
        if not amt.is_finite():
            raise ValueError(f"Non-finite decimal amount: {amt_str!r}")
        aggregates[sku] = aggregates.get(sku, Decimal("0")) + amt

    return {
        sku: str(
            aggregates[sku].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        )
        for sku in sorted(aggregates)
    }
