        sku, amount_str = row

        if sku == '':
            raise ValueError("Empty sku")

        try:
            amount = Decimal(amount_str)
        except (InvalidOperation, ValueError):
            raise ValueError("Malformed decimal amount")

        if not amount.is_finite():
            raise ValueError("Non-finite decimal amount")

        aggregated[sku] = aggregated.get(sku, Decimal('0')) + amount

