```python
import csv
import io
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation


def summarize_csv(text: str) -> dict:
    reader = csv.reader(io.StringIO(text))
    rows = list(reader)

    if not rows:
        raise ValueError("Missing header row")

    header = [h.strip() for h in rows[0]]
    if header != ["sku", "amount"]:
        raise ValueError("Header must be exactly sku,amount")

    aggregates = {}

    for row in rows[1:]:
        # Skip entirely blank rows
        if len(row) == 0 or all(f.strip() == "" for f in row):
            continue

        if len(row) != 2:
            raise ValueError(f"Expected 2 fields, got {len(row)}")

        sku = row[0].strip()
        amount_str = row[1].strip()

        if sku == "":
            raise ValueError("Empty sku")

        try:
            amount = Decimal(amount_str)
        except (InvalidOperation, ValueError):
            raise ValueError(f"Malformed amount: {amount_str!r}")

        if not amount.is_finite():
            raise ValueError(f"Non-finite amount: {amount_str!r}")

        aggregates[sku] = aggregates.get(sku, Decimal("0")) + amount

    result = {}
    for sku in sorted(aggregates):
        rounded = aggregates[sku].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        result[sku] = str(rounded)

    return result
